    );

    TryWriteBookingLog(
        actionType,
        actionTitle,
        description,
        1,
        isInsert ? (int?)1 : null,
        isInsert ? null : (int?)1,
        changeInfo,
        bookingID,
        fullInfo,
        isSuccess,
        errorMessage
