    string actionTitle,
    string description,
    int totalRows,
    int? addCount,
    int? updateCount,
    string filterInfo,
    long? refDataID,
    string extraData,
    bool isSuccess,
    string errorMessage)
{
    try
    {
        var obj = new CRM_Booking();
        obj.GetDataTable(
            "SYS_BookingLog_Add",
            "@FormCode", LOG_FORM_CODE,
            "@FormName", LOG_FORM_NAME,
            "@ActionType", actionType,
            "@ActionTitle", actionTitle,
            "@Description", ToLogDbValue(SafeLogStr(description, 2000)),
            "@TotalRows", totalRows,
            "@AddCount", ToLogDbValue(addCount),
            "@UpdateCount", ToLogDbValue(updateCount),
            "@DeleteCount", DBNull.Value,
            "@FilterInfo", ToLogDbValue(SafeLogStr(filterInfo, 1000)),
            "@RefDataID", ToLogDbValue(refDataID),
            "@ExtraData", ToLogDbValue(extraData),
            "@UserID", DBNull.Value,
            "@Username", User.UserName,
            "@IPAddress", ToLogDbValue(GetClientIPAddress()),
            "@UserAgent", ToLogDbValue(SafeLogStr(Request.UserAgent, 500)),
            "@Url", ToLogDbValue(SafeLogStr(Request.RawUrl, 500)),
            "@SessionID", Session != null ? Session.SessionID : "",
            "@IsSuccess", isSuccess,
            "@ErrorMessage", ToLogDbValue(SafeLogStr(errorMessage, 2000)),
            "@CreatedUser", User.UserName
        );
    }
    catch
    {
        // Không làm gián đoạn nghiệp vụ chính nếu ghi log lỗi
    }
}

private string BuildChangeInfo(BookingLogSnapshot oldSnapshot, bool isInsert)
{
    if (isInsert)
        return "Thêm mới";

    System.Text.StringBuilder sb = new System.Text.StringBuilder();

    AppendFieldChange(sb, "Họ tên", oldSnapshot.PartnerName, objBooking.PartnerName);
    AppendFieldChange(sb, "Ngày sinh", FormatLogDate(oldSnapshot.BirthDate), FormatLogDate(objBooking.BirthDate));
    AppendFieldChange(sb, "Giới tính", FormatLogGender(oldSnapshot.GenderID), FormatLogGender(objBooking.GenderID));
    AppendFieldChange(sb, "Điện thoại", oldSnapshot.Phone, objBooking.Phone);
    AppendFieldChange(sb, "Người VN", FormatLogBool(oldSnapshot.IsVN), FormatLogBool(objBooking.IsVN));
    AppendFieldChange(sb, "Khám mới", FormatLogBool(oldSnapshot.IsFirst), FormatLogBool(objBooking.IsFirst));
    AppendFieldChange(sb, "Khu VIP", FormatLogBool(oldSnapshot.IsVip), FormatLogBool(objBooking.IsVip));
    AppendFieldChange(sb, "Ngày khám", FormatLogDate(oldSnapshot.Date), FormatLogDate(objBooking.Date));
    AppendFieldChange(sb, "Bác sĩ", FormatLogId(oldSnapshot.EmployeeID), FormatLogId(objBooking.EmployeeID));
    AppendFieldChange(sb, "Giờ khám", FormatLogId(oldSnapshot.SlotID), FormatLogId(objBooking.SlotID));
    AppendFieldChange(sb, "Liên lạc 1 - Ngày", FormatLogDate(oldSnapshot.ContactDate1), FormatLogDate(objBooking.ContactDate1));
    AppendFieldChange(sb, "Liên lạc 1 - Kết quả", FormatLogId(oldSnapshot.ContactResultID1), FormatLogId(objBooking.ContactResultID1));
    AppendFieldChange(sb, "Liên lạc 1 - Ghi chú", oldSnapshot.ContactDesc1, objBooking.ContactDesc1);
    AppendFieldChange(sb, "Liên lạc 2 - Ngày", FormatLogDate(oldSnapshot.ContactDate2), FormatLogDate(objBooking.ContactDate2));
    AppendFieldChange(sb, "Liên lạc 2 - Kết quả", FormatLogId(oldSnapshot.ContactResultID2), FormatLogId(objBooking.ContactResultID2));
    AppendFieldChange(sb, "Liên lạc 2 - Ghi chú", oldSnapshot.ContactDesc2, objBooking.ContactDesc2);
    AppendFieldChange(sb, "Trạng thái", FormatLogId(oldSnapshot.BookingStatusID), FormatLogId(objBooking.BookingStatusID));
    AppendFieldChange(sb, "Hủy", FormatLogBool(oldSnapshot.IsCanceled), FormatLogBool(objBooking.IsCanceled));
    AppendFieldChange(sb, "Lý do hủy", oldSnapshot.ChangeReasonDesc, objBooking.ChangeReasonDesc);

    if (sb.Length == 0)
        return "Không đổi";

    return sb.ToString();
}

