private void AppendFieldChange(System.Text.StringBuilder sb, string fieldName, string oldValue, string newValue)
{
    string oldText = NormalizeLogValue(oldValue);
    string newText = NormalizeLogValue(newValue);

    if (oldText == newText)
        return;

    if (sb.Length > 0)
        sb.Append("; ");

    sb.AppendFormat("{0}: {1} -> {2}", fieldName, oldText, newText);
}

