    return value.Value.ToString("dd/MM/yyyy");
}

private string FormatLogGender(int? value)
{
    if (!value.HasValue)
        return "";

    if (value.Value == 1)
        return "Nam";

    if (value.Value == 2)
        return "Nữ";

    return value.Value.ToString();
}

