        snapshot.ContactResultID1 = item.ContactResultID1;
        snapshot.ContactDesc1 = item.ContactDesc1;
        snapshot.ContactDate2 = item.ContactDate2;
        snapshot.ContactResultID2 = item.ContactResultID2;
        snapshot.ContactDesc2 = item.ContactDesc2;
        snapshot.BookingStatusID = item.BookingStatusID;
        snapshot.IsCanceled = item.IsCanceled;
        snapshot.ChangeReasonDesc = item.ChangeReasonDesc;

        return snapshot;
    }
}

