protected string FormatDescription(object description, object filterInfo, object extraData)
{
    string desc = GetLogText(description);
    string filter = GetLogText(filterInfo);
    string extra = GetLogText(extraData);

    if (!string.IsNullOrWhiteSpace(filter) && !IsLogTextAlreadyShown(desc, filter, "Thay đổi:"))
    {
        if (!string.IsNullOrWhiteSpace(desc))
            desc = desc + Environment.NewLine + "Thay đổi: " + filter;
        else
            desc = "Thay đổi: " + filter;
    }

    if (!string.IsNullOrWhiteSpace(extra) && !IsLogTextAlreadyShown(desc, extra, "Chi tiết:"))
    {
        if (!string.IsNullOrWhiteSpace(desc))
            desc = desc + Environment.NewLine + "Chi tiết: " + extra;
        else
            desc = "Chi tiết: " + extra;
    }

    return Server.HtmlEncode(desc ?? "");
}

private bool IsLogTextAlreadyShown(string desc, string text, string sectionLabel)
{
    if (string.IsNullOrWhiteSpace(text))
        return true;

    if (!string.IsNullOrWhiteSpace(desc))
    {
        if (desc.IndexOf(text, StringComparison.OrdinalIgnoreCase) >= 0)
            return true;

        if (!string.IsNullOrWhiteSpace(sectionLabel)
            && desc.IndexOf(sectionLabel, StringComparison.OrdinalIgnoreCase) >= 0)
            return true;
    }

    return false;
}
